int sendto(int fd, void __user *buff, size_t len, unsigned int flags,
           struct sockaddr __user *addr, int addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    int ret = -EFAULT;

    if (len == 0)
        return 0;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    memset(&msg, 0, sizeof(msg));
    msg.msg_name = addr;
    msg.msg_namelen = addr_len;
    msg.msg_iov = (struct iovec __user *)buff;
    msg.msg_iovlen = len;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = flags;

    if (msg.msg_name) {
        struct sockaddr *kaddr;

        kaddr = kmalloc(addr_len, GFP_KERNEL);
        if (!kaddr) {
            ret = -ENOMEM;
            goto out;
        }
        if (copy_from_user(kaddr, addr, addr_len)) {
            kfree(kaddr);
            goto out;
        }
        msg.msg_name = kaddr;
    }

    if (sock->file->f_flags & O_NONBLOCK)
        msg.msg_flags |= MSG_DONTWAIT;

    ret = sock_sendmsg(sock, &msg, len);

    if (msg.msg_name && msg.msg_name != addr)
        kfree(msg.msg_name);

out:
    sockfd_put(sock);
    return ret;
}

