int sendto(int fd, void __user *buff, size_t len, unsigned int flags,
           struct sockaddr __user *addr, int addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    int ret = -EFAULT;
    int nonblock;

    if (len == 0)
        return 0;

    sock = sockfd_lookup(fd, &nonblock);
    if (!sock)
        return -EBADF;

    memset(&msg, 0, sizeof(msg));
    msg.msg_name = addr;
    msg.msg_namelen = addr_len;
    msg.msg_flags = flags;
    msg.msg_iov = NULL;
    msg.msg_iovlen = 0;

    if (buff) {
        msg.msg_iov = kmalloc(sizeof(struct iovec), GFP_KERNEL);
        if (!msg.msg_iov)
            goto out;

        msg.msg_iov[0].iov_base = buff;
        msg.msg_iov[0].iov_len = len;
        msg.msg_iovlen = 1;
    }

    ret = sock_sendmsg(sock, &msg, len);
    if (ret < 0)
        goto out;

    nonblock = 0;

out:
    sockfd_put(sock);
    return ret;
}

int sys_sendto(int fd, void __user *buff, size_t len, unsigned int flags, struct sockaddr __user *addr, int addr_len) {
    struct socket *sock;
    struct msghdr msg;
    int ret;

    if (len > INT_MAX)
        return -EINVAL;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    msg.msg_name = NULL;
    msg.msg_namelen = 0;
    msg.msg_iov = NULL;
    msg.msg_iovlen = 0;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = 0;

    if (buff) {
        struct iovec iov;
        iov.iov_base = buff;
        iov.iov_len = len;
        msg.msg_iov = &iov;
        msg.msg_iovlen = 1;
    }

    if (addr && addr_len > 0) {
        msg.msg_name = kcalloc(addr_len, sizeof(char), GFP_KERNEL);
        if (!msg.msg_name) {
            ret = -ENOMEM;
            goto out;
        }
        if (copy_from_user(msg.msg_name, addr, addr_len)) {
            ret = -EFAULT;
            goto out;
        }
        msg.msg_namelen = addr_len;
    }

    if (sock->file->f_flags & O_NONBLOCK)
        flags |= MSG_DONTWAIT;

    msg.msg_flags = flags;
    ret = sock_sendmsg(sock, &msg, len);
    if (ret < 0)
        goto out;

out:
    if (msg.msg_name)
        kfree(msg.msg_name);
    sockfd_put(sock);
    return ret;
}

#include <linux/uaccess.h>
#include <linux/socket.h>
#include <linux/fdtable.h>

int sendto(int fd, void __user *buff, size_t len, unsigned int flags, struct sockaddr __user *addr, int addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    int ret = -EBADF;
    struct iovec iov;
    struct sockaddr *kaddr = NULL;

    if (len > INT_MAX)
        len = INT_MAX;

    if (!buff || !access_ok(buff, len))
        return -EFAULT;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    iov.iov_base = buff;
    iov.iov_len = len;

    msg.msg_name = NULL;
    msg.msg_namelen = 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = flags;

    if (addr && addr_len > 0) {
        kaddr = kmalloc(addr_len, GFP_KERNEL);
        if (!kaddr) {
            ret = -ENOMEM;
            goto out;
        }

        if (copy_from_user(kaddr, addr, addr_len)) {
            ret = -EFAULT;
            kfree(kaddr);
            goto out;
        }

        msg.msg_name = kaddr;
        msg.msg_namelen = addr_len;
    }

    if (sock->file->f_flags & O_NONBLOCK)
        msg.msg_flags |= MSG_DONTWAIT;

    ret = sock_sendmsg(sock, &msg, len);

    if (kaddr)
        kfree(kaddr);

out:
    sockfd_put(sock);
    return ret;
}
